// === MINEBENCH: CHOo-CHOo TRAIN ===
var PI=Math.PI,abs=Math.abs,MathFloor=Math.floor,MathSin=Math.sin,MathCos=Math.cos,MathSqrt=Math.sqrt,MathMax=Math.max;
function F(v){return MathFloor(v);}

function wheel(cx,cy,cz,radius,type,hubType){
  for(var a=0;a<360;a+=8){
    block(cx+F(radius*MathCos(a*PI/180)),cy+F(radius*MathSin(a*PI/180)),cz,type);
  }
  for(var s=0;s<6;s++){
    var sa=s*60;
    for(var r=2;r<radius;r++){
      block(cx+F(r*MathCos(sa*PI/180)),cy+F(r*MathSin(sa*PI/180)),cz,type);
    }
  }
  block(cx,cy,cz,hubType);
}

var GX=128,GZ=120,railY=2,groundY=0;
var boilerY=railY+5,boilerR=5,boilerLen=22;
var stackZ=GZ+boilerLen,cabX=GX-16;
var dWheelY=railY+1;

// GROUND + TRACK
for(var x=100;x<=160;x++)for(var z=50;z<=200;z++) block(x,groundY,z,'sand');
for(var z=55;z<=195;z++)for(var x=120;x<=136;x++) block(x,railY,z,'oak_log');
for(var z=55;z<=195;z++){block(120,railY+1,z,'iron_block');block(136,railY+1,z,'iron_block');}
for(var z=55;z<=195;z+=2)for(var x=120;x<=136;x+=4)for(var y=groundY;y<railY;y++) block(x,y,z,'cobblestone');

// BOILER
for(var x=-boilerR;x<=boilerR;x++)for(var y=-boilerR;y<=boilerR;y++)for(var z=-boilerLen;z<=boilerLen;z++){
  if(x*x/(boilerR*boilerR)+y*y/(boilerR*boilerR)+z*z/(boilerLen*boilerLen)<=1)
    block(GX+x,boilerY+y,GZ+z,'iron_block');
}
// Firebox
for(var x=-6;x<=6;x++)for(var y=-6;y<=4;y++)for(var z=14;z<=22;z++)
  block(GX+x,boilerY+y,GZ+z,'bricks');
block(GX-1,boilerY+1,GZ+18,'glowstone');block(GX+1,boilerY,GZ+19,'glowstone');block(GX,boilerY-1,GZ+18,'glowstone');

// Bands (variable radius to match ellipsoid cross-section)
for(var band=-3;band<=3;band++){
  var bz=GZ+band*5;
  var zRel=bz-GZ;
  var bandR=F(boilerR*MathSqrt(1-zRel*zRel/(boilerLen*boilerLen)));
  if(bandR<3) bandR=3;
  for(var a=0;a<360;a+=12)
    block(GX+F(bandR*MathCos(a*PI/180)),boilerY+F(bandR*MathSin(a*PI/180)),bz,'iron_block');
}

// Smokestack
for(var y=0;y<=14;y++){
  var sr=y<3?5:F(3*(1-y/14)+3);
  for(var x=-sr;x<=sr;x++)for(var z=-sr;z<=sr;z++)
    if(x*x+z*z<=sr*sr) block(GX+x,boilerY+boilerR+y,stackZ-z,'bricks');
}
for(var x=-6;x<=6;x++)for(var z=-6;z<=6;z++)
  if(x*x+z*z<=36) block(GX+x,boilerY+boilerR+14,stackZ-z,'iron_block');

// Steam dome
for(var x=-4;x<=4;x++)for(var y=-7;y<=0;y++)for(var z=-4;z<=4;z++)
  if(x*x/16+y*y/25+z*z/16<=1) block(GX+x,boilerY+boilerR+y,GZ+2,'iron_block');
block(GX,boilerY+boilerR+7,GZ+2,'gold_block');

// Sand dome
for(var x=-2;x<=2;x++)for(var y=-4;y<=0;y++)for(var z=-2;z<=2;z++)
  if(x*x/4+y*y/9+z*z/4<=1) block(GX+x,boilerY+boilerR+y,GZ+8,'iron_block');

// CAB
var cabY=railY+1;
for(var x=cabX-10;x<=cabX-4;x++)for(var z=-7;z<=7;z++) block(x,cabY,GZ+z,'oak_planks');
for(var x=cabX-10;x<=cabX-4;x++)for(var y=1;y<=9;y++)for(var z=-7;z<=7;z++){
  if(z===-7||z===7||x===cabX-10) block(x,cabY+y,GZ+z,'oak_planks');
}
for(var y=3;y<=9;y++)for(var z=-4;z<=4;z++) block(cabX-4,cabY+y,GZ+z,'oak_planks');
for(var x=cabX-11;x<=cabX-3;x++)for(var z=-8;z<=8;z++){
  var rh=F(2*MathSqrt(MathMax(0,1-z*z/64)))+1;
  for(var ry=0;ry<=rh;ry++) block(x,cabY+9+ry,GZ+z,'bricks');
}
for(var y=3;y<=6;y++){
  for(var z=-5;z<=-2;z++) block(cabX-10,cabY+y,GZ+z,'glass');
  for(var z=2;z<=5;z++) block(cabX-10,cabY+y,GZ+z,'glass');
  for(var x=cabX-9;x<=cabX-5;x++) block(x,cabY+y,GZ+7,'glass');
}
for(var y=1;y<=7;y++) block(cabX-7,cabY+y,GZ+7,'oak_log');
block(cabX-8,cabY+1,GZ-3,'brown_wool');block(cabX-8,cabY+2,GZ-3,'brown_wool');
block(cabX-6,cabY+1,GZ-3,'brown_wool');block(cabX-6,cabY+2,GZ-3,'brown_wool');
block(cabX-5,cabY+3,GZ-5,'iron_block');block(cabX-5,cabY+4,GZ-5,'iron_block');

// COWCATCHER - base at boilerY-boilerR so bottom layer is at groundY=0
var ccBaseY=boilerY-boilerR;
for(var z=0;z<=7;z++){
  var cw=2+F(z*1.2);
  for(var x=-cw;x<=cw;x++)for(var y=-2;y<=0;y++){
    var gy=ccBaseY+y;
    if(gy>=0) block(GX+x,gy,stackZ+z,'iron_block');
  }
}
for(var z=0;z<=7;z++)for(var x=-2;x<=2;x++)
  block(GX+x,ccBaseY,stackZ+z,'iron_block');

// HEADLIGHT
for(var a=0;a<360;a+=15)
  block(GX+F(4*MathCos(a*PI/180)),boilerY+F(4*MathSin(a*PI/180)),stackZ+1,'glass');
block(GX,boilerY,stackZ+1,'glowstone');block(GX,boilerY,stackZ+2,'glowstone');

// DRIVING WHEELS
var dWheelR=3;
var dWheelZs=[GZ-8,GZ,GZ+8];
for(var wi=0;wi<dWheelZs.length;wi++){
  wheel(GX-boilerR-2,dWheelY,dWheelZs[wi],dWheelR,'iron_block','gold_block');
  wheel(GX+boilerR+2,dWheelY,dWheelZs[wi],dWheelR,'iron_block','gold_block');
}
for(var wi=0;wi<dWheelZs.length-1;wi++)for(var z=0;z<=8;z++){
  var zz=dWheelZs[wi]+z;
  block(GX-boilerR-2,dWheelY+dWheelR,zz,'iron_block');
  block(GX+boilerR+2,dWheelY+dWheelR,zz,'iron_block');
}

// LEADING TRUCK
var leadZ=stackZ-4;
for(var side=-1;side<=1;side+=2)
  wheel(GX+side*(boilerR+1),dWheelY-1,leadZ,2,'iron_block','gold_block');

// RUNNING BOARD
for(var z=-boilerLen;z<=boilerLen;z++){
  block(GX-boilerR-3,boilerY-boilerR,GZ+z,'oak_planks');
  block(GX+boilerR+3,boilerY-boilerR,GZ+z,'oak_planks');
}

// HANDRAILS - connected to boiler body
for(var z=-boilerLen+2;z<=boilerLen-2;z++){
  block(GX-boilerR-1,boilerY-2,GZ+z,'iron_block');
  block(GX+boilerR+1,boilerY-2,GZ+z,'iron_block');
  block(GX-boilerR-1,boilerY,GZ+z,'iron_block');
  block(GX+boilerR+1,boilerY,GZ+z,'iron_block');
}
for(var z=-boilerLen+2;z<=boilerLen-2;z+=2){
  block(GX-boilerR-1,boilerY-1,GZ+z,'iron_block');
  block(GX+boilerR+1,boilerY-1,GZ+z,'iron_block');
}

// WHISTLE
for(var x=-3;x<=3;x+=3){
  block(GX+x,boilerY+boilerR+6,GZ+5,'gold_block');
  block(GX+x,boilerY+boilerR+7,GZ+5,'gold_block');
}

// TENDER
var tendX=cabX-12,tendY=railY+1;
for(var x=tendX-12;x<=tendX-4;x++)for(var y=0;y<=7;y++)for(var z=-6;z<=6;z++){
  if(x===tendX-12||x===tendX-4||z===-6||z===6) block(x,tendY+y,GZ+z,'oak_planks');
}
for(var x=tendX-12;x<=tendX-4;x++)for(var z=-6;z<=6;z++) block(x,tendY,GZ+z,'oak_planks');
for(var x=tendX-13;x<=tendX-3;x++)for(var z=-7;z<=7;z++) block(x,tendY+7,GZ+z,'oak_planks');
for(var x=tendX-11;x<=tendX-5;x++)for(var z=-5;z<=5;z++){
  var cx2=(x-(tendX-8))*(x-(tendX-8))/16;
  var cz2=z*z/25;
  var coalH=F(3*(1-cx2-cz2)+0.5);
  if(coalH>0) for(var cy=0;cy<coalH;cy++) block(x,tendY+8+cy,GZ+z,'black_wool');
}
for(var z=-5;z<=5;z+=2){
  block(tendX-12,tendY+1,GZ+z,'iron_block');
  block(tendX-12,tendY+3,GZ+z,'iron_block');
  block(tendX-12,tendY+5,GZ+z,'iron_block');
  block(tendX-4,tendY+1,GZ+z,'iron_block');
  block(tendX-4,tendY+3,GZ+z,'iron_block');
  block(tendX-4,tendY+5,GZ+z,'iron_block');
}
for(var wi=0;wi<2;wi++){
  var twz=GZ-3+wi*6;
  for(var side=-1;side<=1;side+=2)
    wheel(tendX+side*10,dWheelY-1,twz,2,'iron_block','gold_block');
}
for(var z=-3;z<=2;z++) block(tendX-4,tendY+3,GZ+z,'iron_block');

// PASSENGER CAR
var carX=tendX-22,carY=railY+1;
for(var x=carX-18;x<=carX-8;x++)for(var y=0;y<=11;y++)for(var z=-6;z<=6;z++){
  var isW=(x===carX-18||x===carX-8||z===-6||z===6);
  if(isW&&y>0&&y<11) block(x,carY+y,GZ+z,'white_wool');
  if(y===0||y===11) block(x,carY+y,GZ+z,'bricks');
}
for(var x=carX-17;x<=carX-9;x++)for(var z=-5;z<=5;z++)
  for(var wy=3;wy<=6;wy++) block(x,carY+wy,GZ+z,'glass');
for(var y=1;y<=9;y++) block(carX-13,carY+y,GZ+6,'oak_planks');
for(var x=carX-19;x<=carX-7;x++)for(var z=-7;z<=7;z++){
  var rh=F(2*MathSqrt(MathMax(0,1-z*z/49)))+1;
  for(var ry=0;ry<=rh;ry++) block(x,carY+11+ry,GZ+z,'bricks');
}
for(var x=carX-18;x<=carX-8;x++)for(var z=-6;z<=6;z++){
  block(x,carY+3,GZ+z,'red_wool');
  block(x,carY+7,GZ+z,'red_wool');
}
for(var wi=0;wi<2;wi++){
  var pcz=GZ-4+wi*8;
  for(var side=-1;side<=1;side+=2)
    wheel(carX+side*9,dWheelY-1,pcz,2,'iron_block','gold_block');
}
for(var z=-2;z<=3;z++) block(carX-8,carY+3,GZ+z,'iron_block');

// SUPPORT PILLARS
function pillar(px,pz){
  for(var y=groundY;y<railY+1;y++) block(px,y,pz,'cobblestone');
}
for(var wi=0;wi<dWheelZs.length;wi++){pillar(GX-boilerR-2,dWheelZs[wi]);pillar(GX+boilerR+2,dWheelZs[wi]);}
for(var side=-1;side<=1;side+=2) pillar(GX+side*(boilerR+1),leadZ);
for(var wi=0;wi<2;wi++){var twz=GZ-3+wi*6;pillar(tendX-10,twz);pillar(tendX+10,twz);}
for(var wi=0;wi<2;wi++){var pcz=GZ-4+wi*8;pillar(carX-9,pcz);pillar(carX+9,pcz);}

// SCENERY
function tree(tx,ty,tz){
  for(var y=0;y<6;y++) block(tx,ty+y,tz,'oak_log');
  for(var x=-3;x<=3;x++)for(var y=0;y<=3;y++)for(var z=-3;z<=3;z++)
    if(x*x+y*y+z*z<=12) block(tx+x,ty+6+y,tz+z,'oak_leaves');
}
tree(108,groundY,80);tree(148,groundY,90);tree(110,groundY,170);
tree(150,groundY,160);tree(105,groundY,130);tree(155,groundY,140);
for(var i=0;i<8;i++){
  var bx=105+F(i*4.3),bz=60+F(i*13.7);
  block(bx,groundY+1,bz,'oak_leaves');block(bx+1,groundY+1,bz,'oak_leaves');block(bx,groundY+2,bz,'oak_leaves');
}
for(var x=115;x<=141;x++)for(var z=185;z<=195;z++) block(x,railY+2,z,'stone_bricks');
for(var x=115;x<=141;x++){block(x,railY+3,185,'oak_log');block(x,railY+3,195,'oak_log');}
for(var x=115;x<=141;x+=7)for(var y=0;y<=5;y++){block(x,railY+2+y,185,'oak_log');block(x,railY+2+y,195,'oak_log');}
for(var x=113;x<=143;x++)for(var z=183;z<=197;z++) block(x,railY+7,z,'oak_planks');
block(120,railY+3,188,'oak_planks');block(121,railY+3,188,'oak_planks');block(122,railY+3,188,'oak_planks');
block(120,railY+4,188,'oak_planks');block(122,railY+4,188,'oak_planks');

// SMOKE
for(var i=0;i<40;i++){
  var sAngle=i*0.7;
  var sx=GX+F(4*MathSin(sAngle))+F(i*0.12);
  var sy=boilerY+boilerR+15+F(i*0.5);
  var sz=stackZ-F(3*MathCos(sAngle))-F(i*1.3);
  var sr=F(1+i/15);
  for(var dx=-sr;dx<=sr;dx++)for(var dy=-sr;dy<=sr;dy++)for(var dz=-sr;dz<=sr;dz++)
    if(dx*dx+dy*dy+dz*dz<=sr*sr+1) block(sx+dx,sy+dy,sz+dz,'white_wool');
}
